import {
  PipeTransform,
  Injectable,
  BadRequestException,
} from '@nestjs/common'
import type { ZodType } from 'zod'

@Injectable()
export class ZodValidationPipe implements PipeTransform {
  constructor(private readonly schema: ZodType) {}

  transform(value: unknown) {
    const result = this.schema.safeParse(value)
    if (!result.success) {
      throw new BadRequestException({
        type: 'https://taxdesk.pk/problems/validation-error',
        title: 'Validation failed',
        status: 400,
        errors: result.error.flatten().fieldErrors,
      })
    }
    return result.data
  }
}

import type { Prisma } from '@prisma/client'
import { beforeEach, describe, expect, it, vi } from 'vitest'

import { INV1_ERROR, PrismaRlsClient } from './prisma-rls.client'
import type { PrismaService } from './prisma.service'
import { rlsIdentityStorage, rlsTransactionStorage } from './rls-context.store'

const identity = {
  firmId: 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',
  userId: 'bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb',
  sessionType: 'staff' as const,
}

function createMockTx(id: string): Prisma.TransactionClient {
  return {
    $executeRaw: vi.fn().mockResolvedValue(0),
    $queryRaw: vi.fn(),
    __id: id,
  } as unknown as Prisma.TransactionClient
}

describe('PrismaRlsClient.withRlsContext', () => {
  let transactionCount: number
  let prismaRls: PrismaRlsClient
  let outerTx: Prisma.TransactionClient
  let innerTransactionFn: ReturnType<typeof vi.fn>

  beforeEach(() => {
    transactionCount = 0
    innerTransactionFn = vi.fn(async (callback: (tx: Prisma.TransactionClient) => Promise<unknown>) => {
      transactionCount += 1
      outerTx = createMockTx(`tx-${transactionCount}`)
      return callback(outerTx)
    })

    const prisma = {
      $transaction: innerTransactionFn,
    } as unknown as PrismaService

    prismaRls = new PrismaRlsClient(prisma)
  })

  it('throws fail-closed when no ALS identity is present', async () => {
    await expect(prismaRls.withRlsContext(() => Promise.resolve('noop'))).rejects.toThrow(INV1_ERROR)
    expect(innerTransactionFn).not.toHaveBeenCalled()
  })

  it('opens separate transactions for sequential withRlsContext calls (IC-1)', async () => {
    await rlsIdentityStorage.run(identity, async () => {
      await prismaRls.withRlsContext(() => Promise.resolve('first'))
      await prismaRls.withRlsContext(() => Promise.resolve('second'))
    })

    expect(transactionCount).toBe(2)
  })

  it('reuses the active transaction for nested withRlsContext (IC-1)', async () => {
    await rlsIdentityStorage.run(identity, async () => {
      await prismaRls.withRlsContext(async (outer) => {
        await prismaRls.withRlsContext(async (inner) => {
          expect(inner).toBe(outer)
        })
      })
    })

    expect(transactionCount).toBe(1)
  })

  it('rolls back atomically when an inner operation fails', async () => {
    const rollbackSpy = vi.fn()

    innerTransactionFn.mockImplementation(
      async (callback: (tx: Prisma.TransactionClient) => Promise<unknown>) => {
        const tx = createMockTx('atomic')
        try {
          return await callback(tx)
        } catch (error) {
          rollbackSpy(error)
          throw error
        }
      },
    )

    await rlsIdentityStorage.run(identity, async () => {
      await expect(
        prismaRls.withRlsContext(async (tx) => {
          await tx.$executeRaw`SELECT 1`
          throw new Error('second step failed')
        }),
      ).rejects.toThrow('second step failed')
    })

    expect(rollbackSpy).toHaveBeenCalledTimes(1)
  })

  it('sets RLS session variables via set_config on new transactions', async () => {
    await rlsIdentityStorage.run(identity, async () => {
      await prismaRls.withRlsContext((tx) => {
        expect(tx.$executeRaw).toHaveBeenCalled()
        return Promise.resolve()
      })
    })
  })

  it('does not nest rlsTransactionStorage outside an active transaction', () => {
    expect(rlsTransactionStorage.getStore()).toBeUndefined()
  })
})

import { randomUUID } from 'node:crypto'

import { Inject, Injectable, Logger } from '@nestjs/common'
import type { Prisma } from '@prisma/client'
import {
  DocumentExtractionStatus,
  DocumentProcessingStatus,
  DocumentReviewStatus,
  DocumentStatus,
} from '@prisma/client'
import {
  getExtractionSchemaBundle,
  resolveExtractionKind,
} from '@taxdesk/schemas'

import { PrismaRlsClient } from '../../database/prisma-rls.client'
import { PRE_AUTH_USER_ID, withStaffBootstrapContext } from '../auth/rls-bootstrap.util'
import {
  OBJECT_STORAGE_PROVIDER,
  type ObjectStorageProvider,
} from '../storage/object-storage.interface'

import type { AiExtractionProvider } from './ai-extraction.provider'
import type { AiExtractionJob } from './ai-extraction.service'
import { zodSchemaToOpenAiJsonSchema } from './extraction-json-schema.util'
import { OpenAiExtractionError } from './openai.errors'

export interface ProvisionalExtractedFields {
  kind: string
  provisional: true
  awaitingReview: true
  payload: unknown
  validationIssues: Array<{ field: string; issue: string; severity: 'error' | 'warning' }>
  fieldConfidence: Record<string, number>
  overallConfidence: number
  extractedAt: string
}

@Injectable()
export class AiExtractionHandlerService {
  private readonly logger = new Logger(AiExtractionHandlerService.name)

  constructor(
    private readonly prismaRls: PrismaRlsClient,
    @Inject('AiExtractionProvider')
    private readonly aiProvider: AiExtractionProvider,
    @Inject(OBJECT_STORAGE_PROVIDER)
    private readonly storage: ObjectStorageProvider,
  ) {}

  async processJob(job: AiExtractionJob, actorUserId?: string): Promise<void> {
    const userId = actorUserId ?? PRE_AUTH_USER_ID

    await withStaffBootstrapContext(job.firmId, userId, async () => {
      await this.prismaRls.withRlsContext(async (tx) => {
        const doc = await tx.document.findFirst({
          where: { id: job.documentId, firmId: job.firmId },
        })
        if (!doc) {
          this.logger.warn(`Document ${job.documentId} not found — skipping`)
          return
        }

        if (
          doc.extractionStatus === DocumentExtractionStatus.COMPLETE &&
          doc.status === DocumentStatus.EXTRACTED
        ) {
          this.logger.log(`Document ${job.documentId} already extracted — idempotent skip`)
          return
        }

        await tx.document.update({
          where: { id: doc.id },
          data: {
            status: DocumentStatus.PROCESSING,
            processingStatus: DocumentProcessingStatus.EXTRACTING,
            extractionStatus: DocumentExtractionStatus.IN_PROGRESS,
          },
        })

        try {
          const kind = resolveExtractionKind({
            documentType: job.documentType ?? doc.documentType,
            category: doc.category,
          })
          const bundle = getExtractionSchemaBundle(kind)

          if (!bundle) {
            await tx.document.update({
              where: { id: doc.id },
              data: {
                extractionStatus: DocumentExtractionStatus.SKIPPED,
                processingStatus: DocumentProcessingStatus.READY,
                status: DocumentStatus.UPLOADED,
              },
            })
            return
          }

          const jsonSchema = zodSchemaToOpenAiJsonSchema(bundle.zodSchema, `${kind}_extraction`)

          const raw = await this.aiProvider.extract({
            fileId: job.storageKey,
            documentType: kind,
            jsonSchema,
            firmId: job.firmId,
            documentId: job.documentId,
            mimeType: doc.mimeType,
            loadFileBytes: () => this.storage.getObject(job.storageKey),
          })

          const parsed = bundle.zodSchema.safeParse(raw.fields)
          if (!parsed.success) {
            throw new OpenAiExtractionError(
              `Extraction failed Zod validation: ${parsed.error.message}`,
            )
          }

          const validationIssues = bundle.validate(parsed.data)
          const hasBlockingError = validationIssues.some((i) => i.severity === 'error')
          if (hasBlockingError) {
            throw new OpenAiExtractionError(
              `Deterministic validation failed: ${validationIssues.map((i) => i.field).join(', ')}`,
            )
          }

          const provisional: ProvisionalExtractedFields = {
            kind,
            provisional: true,
            awaitingReview: true,
            payload: parsed.data,
            validationIssues,
            fieldConfidence: raw.fieldConfidence,
            overallConfidence: raw.overallConfidence,
            extractedAt: new Date().toISOString(),
          }

          await tx.document.update({
            where: { id: doc.id },
            data: {
              extractedFields: provisional as unknown as Prisma.InputJsonValue,
              confidence: raw.overallConfidence,
              documentType: kind,
              status: DocumentStatus.EXTRACTED,
              processingStatus: DocumentProcessingStatus.READY,
              extractionStatus: DocumentExtractionStatus.COMPLETE,
              reviewStatus: DocumentReviewStatus.IN_REVIEW,
            },
          })

          await tx.aiCallLog.create({
            data: {
              id: randomUUID(),
              firmId: job.firmId,
              documentId: job.documentId,
              model: raw.model ?? 'unknown',
              operation: 'extract',
              inputTokens: raw.usage?.inputTokens ?? 0,
              outputTokens: raw.usage?.outputTokens ?? 0,
              costPaisaEst: BigInt(raw.usage?.costPaisaEst ?? 0),
              status: 'success',
            },
          })
        } catch (err) {
          const message = err instanceof Error ? err.message : String(err)
          this.logger.error(`AI extraction failed for ${job.documentId}: ${message}`)

          await tx.aiCallLog.create({
            data: {
              id: randomUUID(),
              firmId: job.firmId,
              documentId: job.documentId,
              model: 'n/a',
              operation: 'extract',
              inputTokens: 0,
              outputTokens: 0,
              costPaisaEst: 0n,
              status: 'failed',
              errorMessage: message.slice(0, 500),
            },
          })

          await tx.document.update({
            where: { id: doc.id },
            data: {
              status: DocumentStatus.FAILED,
              processingStatus: DocumentProcessingStatus.FAILED,
              extractionStatus: DocumentExtractionStatus.FAILED,
            },
          })

          throw err
        }
      })
    })
  }
}

import { UnauthorizedException } from '@nestjs/common'
import bcrypt from 'bcrypt'
import { beforeEach, describe, expect, it, vi } from 'vitest'

import type { PrismaRlsClient } from '../../database/prisma-rls.client'
import type { NotificationProvider } from '../notifications/notification.provider'

import { BCRYPT_PASSWORD_COST, INVALID_CREDENTIALS_MESSAGE } from './auth.constants'
import { AuthService } from './auth.service'
import type { TenantBootstrapService } from './tenant-bootstrap.service'
import type { TokenService } from './token.service'

describe('AuthService.login', () => {
  let service: AuthService
  let tenantBootstrap: TenantBootstrapService
  let prismaRls: PrismaRlsClient
  let tokenService: TokenService
  let notifications: NotificationProvider
  let resolveFirmMock: ReturnType<typeof vi.fn>
  let withRlsContextMock: ReturnType<typeof vi.fn>

  const meta = { ipAddress: '127.0.0.1', userAgent: 'vitest' }
  const firmId = '11111111-1111-1111-1111-111111111111'

  beforeEach(() => {
    resolveFirmMock = vi.fn()
    withRlsContextMock = vi.fn()

    tenantBootstrap = {
      resolveFirm: resolveFirmMock,
    } as unknown as TenantBootstrapService

    prismaRls = {
      withRlsContext: withRlsContextMock,
    } as unknown as PrismaRlsClient

    tokenService = {
      issuePartialJwt: vi.fn().mockReturnValue({ accessToken: 'partial-token', jti: 'jti' }),
    } as unknown as TokenService

    notifications = {
      sendEmail: vi.fn(),
      sendSms: vi.fn(),
    }

    service = new AuthService(tenantBootstrap, prismaRls, tokenService, notifications)
  })

  async function expectInvalidCredentials(promise: Promise<unknown>) {
    try {
      await promise
      throw new Error('expected rejection')
    } catch (err) {
      expect(err).toBeInstanceOf(UnauthorizedException)
      const response = (err as UnauthorizedException).getResponse() as { title: string }
      expect(response.title).toBe(INVALID_CREDENTIALS_MESSAGE)
    }
  }

  it('returns generic 401 for unknown firm', async () => {
    resolveFirmMock.mockResolvedValue(null)
    await expectInvalidCredentials(
      service.login({ firmSlug: 'missing', email: 'a@b.com', password: 'x' }, meta),
    )
  })

  it('returns generic 401 for unknown user and runs bcrypt compare', async () => {
    resolveFirmMock.mockResolvedValue({ firmId, idleTimeoutMinutes: 0 })
    withRlsContextMock.mockResolvedValue(null)
    const compareSpy = vi.spyOn(bcrypt, 'compare')

    await expectInvalidCredentials(
      service.login({ firmSlug: 'firm', email: 'a@b.com', password: 'x' }, meta),
    )
    expect(compareSpy).toHaveBeenCalled()
  })

  it('returns generic 401 for wrong password', async () => {
    const hash = await bcrypt.hash('correct', BCRYPT_PASSWORD_COST)
    resolveFirmMock.mockResolvedValue({ firmId, idleTimeoutMinutes: 0 })
    withRlsContextMock
      .mockResolvedValueOnce({
        id: 'user-1',
        email: 'a@b.com',
        passwordHash: hash,
        failedLoginCount: 0,
        lockedUntil: null,
        totpEnabled: true,
        role: 'OWNER',
      })
      .mockResolvedValueOnce({ lockedUntil: null, failedLoginCount: 1, firmName: null })

    await expectInvalidCredentials(
      service.login({ firmSlug: 'firm', email: 'a@b.com', password: 'wrong' }, meta),
    )
  })

  it('returns generic 401 for locked account', async () => {
    const hash = await bcrypt.hash('pass', BCRYPT_PASSWORD_COST)
    resolveFirmMock.mockResolvedValue({ firmId, idleTimeoutMinutes: 0 })
    withRlsContextMock.mockResolvedValue({
      id: 'user-1',
      email: 'a@b.com',
      passwordHash: hash,
      failedLoginCount: 3,
      lockedUntil: new Date(Date.now() + 60_000),
      totpEnabled: true,
      role: 'OWNER',
    })

    await expectInvalidCredentials(
      service.login({ firmSlug: 'firm', email: 'a@b.com', password: 'pass' }, meta),
    )
  })

  it('returns requiresTotpSetup when totp disabled', async () => {
    const hash = await bcrypt.hash('pass', BCRYPT_PASSWORD_COST)
    resolveFirmMock.mockResolvedValue({ firmId, idleTimeoutMinutes: 0 })
    withRlsContextMock
      .mockResolvedValueOnce({
        id: 'user-1',
        email: 'a@b.com',
        passwordHash: hash,
        failedLoginCount: 0,
        lockedUntil: null,
        totpEnabled: false,
        role: 'OWNER',
      })
      .mockResolvedValueOnce(undefined)

    const result = await service.login({ firmSlug: 'firm', email: 'a@b.com', password: 'pass' }, meta)
    expect(result).toEqual({ accessToken: 'partial-token', requiresTotpSetup: true })
  })

  it('returns requiresTotp when totp enabled', async () => {
    const hash = await bcrypt.hash('pass', BCRYPT_PASSWORD_COST)
    resolveFirmMock.mockResolvedValue({ firmId, idleTimeoutMinutes: 0 })
    withRlsContextMock
      .mockResolvedValueOnce({
        id: 'user-1',
        email: 'a@b.com',
        passwordHash: hash,
        failedLoginCount: 0,
        lockedUntil: null,
        totpEnabled: true,
        role: 'OWNER',
      })
      .mockResolvedValueOnce(undefined)

    const result = await service.login({ firmSlug: 'firm', email: 'a@b.com', password: 'pass' }, meta)
    expect(result).toEqual({ accessToken: 'partial-token', requiresTotp: true })
  })

  it('locks after third failure in single withRlsContext', async () => {
    const hash = await bcrypt.hash('pass', BCRYPT_PASSWORD_COST)
    resolveFirmMock.mockResolvedValue({ firmId, idleTimeoutMinutes: 0 })
    withRlsContextMock
      .mockResolvedValueOnce({
        id: 'user-1',
        email: 'a@b.com',
        passwordHash: hash,
        failedLoginCount: 2,
        lockedUntil: null,
        totpEnabled: true,
        role: 'OWNER',
      })
      .mockImplementationOnce(async (fn) => {
        const tx = {
          user: { update: vi.fn() },
          auditLog: { create: vi.fn() },
          firm: { findUnique: vi.fn().mockResolvedValue({ name: 'Acme Tax' }) },
        }
        return fn(tx as never)
      })

    await expectInvalidCredentials(
      service.login({ firmSlug: 'firm', email: 'a@b.com', password: 'wrong' }, meta),
    )

    expect(withRlsContextMock).toHaveBeenCalledTimes(2)
  }, 20_000)
})

import { HttpException, UnauthorizedException } from '@nestjs/common'
import bcrypt from 'bcrypt'
import { beforeEach, describe, expect, it, vi } from 'vitest'

import type { PrismaRlsClient } from '../../database/prisma-rls.client'
import type { NotificationProvider } from '../notifications/notification.provider'

import {
  OtpService,
  OTP_SEND_RESPONSE,
  contactHmac,
  normaliseContact,
} from './otp.service'
import type { PortalClientLookup } from './portal-client.lookup'
import type { TenantBootstrapService } from './tenant-bootstrap.service'
import type { TokenService } from './token.service'

describe('OtpService', () => {
  let service: OtpService
  let tenantBootstrap: TenantBootstrapService
  let prismaRls: PrismaRlsClient
  let tokenService: TokenService
  let portalLookup: PortalClientLookup
  let notifications: NotificationProvider
  let resolveFirmMock: ReturnType<typeof vi.fn>
  let withRlsContextMock: ReturnType<typeof vi.fn>
  let sendEmailMock: ReturnType<typeof vi.fn>

  const firmId = '11111111-1111-1111-1111-111111111111'
  const clientId = '33333333-3333-3333-3333-333333333333'

  beforeEach(() => {
    resolveFirmMock = vi.fn().mockResolvedValue({ firmId, idleTimeoutMinutes: 0 })
    withRlsContextMock = vi.fn()
    sendEmailMock = vi.fn()

    tenantBootstrap = {
      resolveFirm: resolveFirmMock,
      prismaBootstrap: {} as never,
      onModuleDestroy: vi.fn(),
    } as unknown as TenantBootstrapService
    prismaRls = { withRlsContext: withRlsContextMock } as unknown as PrismaRlsClient
    tokenService = {
      issueFullJwt: vi.fn().mockReturnValue({ accessToken: 'access', jti: 'jti' }),
      issueRefreshToken: vi.fn().mockResolvedValue({ rawToken: 'refresh.raw', recordId: '1' }),
    } as unknown as TokenService
    portalLookup = { resolveClientId: vi.fn().mockResolvedValue(clientId) }
    notifications = { sendEmail: sendEmailMock, sendSms: vi.fn() }

    service = new OtpService(tenantBootstrap, prismaRls, tokenService, portalLookup, notifications)
  })

  it('sendOtp returns same response for unknown firm', async () => {
    resolveFirmMock.mockResolvedValue(null)
    const res = await service.sendOtp(
      { firmSlug: 'x', contact: 'a@b.com', channel: 'email' },
      {},
    )
    expect(res).toEqual(OTP_SEND_RESPONSE)
    expect(sendEmailMock).not.toHaveBeenCalled()
  })

  it('contact normalisation produces same HMAC', () => {
    const a = contactHmac(normaliseContact('User@Example.Com'))
    const b = contactHmac(normaliseContact('user@example.com'))
    expect(a).toBe(b)
  })

  it('HMAC is deterministic across calls', () => {
    expect(contactHmac('test@example.com')).toBe(contactHmac('test@example.com'))
  })

  it('rate limits after 3 sends per hour', async () => {
    withRlsContextMock.mockResolvedValueOnce(3)
    await expect(
      service.sendOtp({ firmSlug: 'f', contact: 'a@b.com', channel: 'email' }, {}),
    ).rejects.toBeInstanceOf(HttpException)
  })

  it('sendOtp inserts OTP and sends email outside transaction order', async () => {
    const calls: string[] = []
    withRlsContextMock
      .mockResolvedValueOnce(0)
      .mockImplementation((fn: (tx: unknown) => Promise<unknown>) => {
        calls.push('tx-start')
        const result = fn({
          otpCode: { create: vi.fn(), count: vi.fn().mockResolvedValue(0) },
          auditLog: { create: vi.fn() },
        } as never)
        calls.push('tx-end')
        return result
      })
    sendEmailMock.mockImplementation(() => {
      calls.push('email')
      return Promise.resolve()
    })

    await service.sendOtp({ firmSlug: 'f', contact: 'a@b.com', channel: 'email' }, {})
    expect(calls.indexOf('tx-end')).toBeLessThan(calls.indexOf('email'))
  })

  it('verify success consumes OTP and issues tokens', async () => {
    const otp = '123456'
    const otpHash = await bcrypt.hash(otp, 10)
    const record = {
      id: 'otp-1',
      otpHash,
      attempts: 0,
      usedAt: null,
      expiresAt: new Date(Date.now() + 60_000),
    }

    withRlsContextMock.mockResolvedValueOnce(record).mockResolvedValueOnce(undefined)

    const result = await service.verifyOtp(
      { firmSlug: 'f', contact: 'a@b.com', code: otp },
      {},
    )
    expect(result.accessToken).toBe('access')
    expect(result.rawRefreshToken).toBe('refresh.raw')
  })

  it('rejects reuse after consumed OTP', async () => {
    withRlsContextMock.mockResolvedValueOnce(null)
    await expect(
      service.verifyOtp({ firmSlug: 'f', contact: 'a@b.com', code: '123456' }, {}),
    ).rejects.toBeInstanceOf(UnauthorizedException)
  })

  it('rejects expired OTP', async () => {
    withRlsContextMock.mockResolvedValueOnce(null)
    await expect(
      service.verifyOtp({ firmSlug: 'f', contact: 'a@b.com', code: '123456' }, {}),
    ).rejects.toBeInstanceOf(UnauthorizedException)
  })

  it('invalidates OTP after 3 wrong attempts', async () => {
    const otpHash = await bcrypt.hash('999999', 10)
    const record = {
      id: 'otp-1',
      otpHash,
      attempts: 2,
      usedAt: null,
      expiresAt: new Date(Date.now() + 60_000),
    }
    const update = vi.fn()

    withRlsContextMock
      .mockResolvedValueOnce(record)
      .mockImplementationOnce((fn: (tx: unknown) => Promise<unknown>) =>
        fn({ otpCode: { update }, auditLog: { create: vi.fn() } } as never),
      )

    await expect(
      service.verifyOtp({ firmSlug: 'f', contact: 'a@b.com', code: '000000' }, {}),
    ).rejects.toBeInstanceOf(UnauthorizedException)

    expect(update).toHaveBeenCalledWith(
      expect.objectContaining({
        data: expect.objectContaining({ attempts: 3, usedAt: expect.any(Date) as Date }),
      }),
    )
  })

  it('verify uses latest OTP record (replacement)', async () => {
    const findFirst = vi.fn().mockResolvedValue({
      id: 'latest',
      otpHash: await bcrypt.hash('999999', 10),
      attempts: 0,
      usedAt: null,
      expiresAt: new Date(Date.now() + 60_000),
    })
    withRlsContextMock
      .mockImplementationOnce((fn: (tx: unknown) => Promise<unknown>) =>
        fn({ otpCode: { findFirst } } as never),
      )
      .mockImplementationOnce((fn: (tx: unknown) => Promise<unknown>) =>
        fn({ otpCode: { update: vi.fn() }, auditLog: { create: vi.fn() } } as never),
      )

    await expect(
      service.verifyOtp({ firmSlug: 'f', contact: 'a@b.com', code: '123456' }, {}),
    ).rejects.toBeInstanceOf(UnauthorizedException)

    expect(findFirst).toHaveBeenCalledWith(
      expect.objectContaining({ orderBy: { createdAt: 'desc' } }),
    )
  })

  it('verify errors share same problem title', async () => {
    withRlsContextMock.mockResolvedValue(null)
    const run = () => service.verifyOtp({ firmSlug: 'f', contact: 'a@b.com', code: '000000' }, {})
    await expect(run()).rejects.toMatchObject({
      response: expect.objectContaining({ title: 'Invalid code.' }) as { title: string },
    })
  })
})

import { JwtService } from '@nestjs/jwt'
import { beforeEach, describe, expect, it, vi } from 'vitest'

import type { PrismaRlsClient } from '../../database/prisma-rls.client'
import type { AuditService } from '../audit/audit.service'

import { InvalidRefreshTokenError, ReplayAttackError } from './auth.errors'
import {
  TokenService,
  hashRefreshToken,
  parseRefreshTokenRaw,
  buildRefreshTokenRaw,
} from './token.service'

describe('TokenService', () => {
  let service: TokenService
  let jwtService: JwtService
  let prismaRls: PrismaRlsClient
  let audit: AuditService
  let withRlsContextMock: ReturnType<typeof vi.fn>
  let withPreAuthFirmContextMock: ReturnType<typeof vi.fn>
  let auditLogMock: ReturnType<typeof vi.fn>

  beforeEach(() => {
    process.env['JWT_ACCESS_SECRET'] = 'a'.repeat(48)
    process.env['JWT_REFRESH_SECRET'] = 'b'.repeat(48)

    jwtService = new JwtService({ secret: process.env['JWT_ACCESS_SECRET'] })
    auditLogMock = vi.fn()
    audit = { log: auditLogMock } as unknown as AuditService

    withRlsContextMock = vi.fn()
    withPreAuthFirmContextMock = vi.fn()

    prismaRls = {
      withRlsContext: withRlsContextMock,
      withPreAuthFirmContext: withPreAuthFirmContextMock,
    } as unknown as PrismaRlsClient

    service = new TokenService(jwtService, prismaRls, audit)
  })

  it('stores only SHA-256 hash — raw token differs from tokenHash', async () => {
    const firmId = '11111111-1111-1111-1111-111111111111'
    const userId = '22222222-2222-2222-2222-222222222222'
    let capturedHash = ''

    withRlsContextMock.mockImplementation((fn: (tx: unknown) => Promise<unknown>) => {
      const tx = {
        refreshToken: {
