        },
        user: { findUnique: vi.fn().mockResolvedValue({ isActive: true, role: 'OWNER', lastActivityAt: new Date() }) },
        firm: { findUnique: vi.fn().mockResolvedValue({ idleTimeoutMinutes: 0 }) },
        auditLog: { create: vi.fn() },
      }
